const enc = new TextEncoder();
function b64urlEnc(s){ return btoa(unescape(encodeURIComponent(s))).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,""); }
function b64urlDec(s){ return decodeURIComponent(escape(atob(s.replace(/-/g,"+").replace(/_/g,"/")))); }
function b64raw(b){ return btoa(b).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,""); }
async function hmac(d){ const k=await crypto.subtle.importKey("raw",enc.encode(SECRET),{name:"HMAC",hash:"SHA-256"},false,["sign"]); const s=await crypto.subtle.sign("HMAC",k,enc.encode(d)); let b=""; const a=new Uint8Array(s); for(let i=0;i<a.length;i++)b+=String.fromCharCode(a[i]); return b64raw(b); }
